import * as U from '../ui.js';
let month=U.TODAY.slice(0,7)+'-01',type='all';
const update=U.mount(()=>{if(U.db.monthly_budgets.length&&!U.db.monthly_budgets.some(b=>b.month_start===month))month=U.db.monthly_budgets.slice().sort((a,b)=>b.month_start.localeCompare(a.month_start))[0].month_start;let b=U.budgetSummary(month),tx=b.transactions.filter(t=>type==='all'||t.transaction_type===type).sort((a,b)=>b.transaction_date.localeCompare(a.transaction_date)),categories={};b.transactions.filter(t=>t.transaction_type==='expense').forEach(t=>categories[t.category]=(categories[t.category]||0)+Number(t.amount));return U.heading('Know where your money goes','A little financial clarity.','Your spending, your priorities, your peace of mind.',b.budget?U.button('Record spending','transactions','',{monthly_budget_id:b.budget.id,transaction_date:month===U.TODAY.slice(0,7)+'-01'?U.TODAY:month}):U.button('Set monthly budget','monthly_budgets','',{month_start:month}))+`<div class="toolbar"><label class="small muted">Budget month <select id="budget-month" aria-label="Budget month">${U.db.monthly_budgets.slice().sort((a,b)=>b.month_start.localeCompare(a.month_start)).map(m=>`<option value="${m.month_start}" ${m.month_start===month?'selected':''}>${U.date(m.month_start,{month:'long',year:'numeric'})}</option>`).join('')}</select></label><div class="actions">${b.budget?U.button('Edit limit','monthly_budgets',b.budget.id):''}${U.button('New month','monthly_budgets','',{month_start:b.budget?new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),1)).toISOString().slice(0,10):month})}</div></div><div class="cards">${U.stat('Monthly limit',U.money(b.budget?.spending_limit||0,b.budget?.currency_code),'Your spending plan','wallet')}${U.stat('Spent so far',U.money(b.spent,b.budget?.currency_code),'Expenses this month','wallet')}${U.stat('Remaining',U.money(b.remaining,b.budget?.currency_code),b.remaining<0?'You are over your limit':'Available within your limit','check')}${U.stat('Income recorded',U.money(b.income,b.budget?.currency_code),'Tracked separately from your spending limit','wallet')}</div><div class="dashboard-grid"><div class="stack">${U.section('Transaction history',`<div class="toolbar"><div class="tabs">${['all','expense','income'].map(t=>`<button data-type="${t}" class="${type===t?'active':''}">${t==='all'?'All transactions':t==='expense'?'Expenses':'Income'}</button>`).join('')}</div></div><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Category</th><th>Date</th><th>Amount</th><th></th></tr></thead><tbody>${tx.map(t=>`<tr><td>${U.esc(t.description||t.transaction_type)}</td><td>${U.tag(t.category)}</td><td>${U.date(t.transaction_date)}</td><td style="font-weight:650;color:${t.transaction_type==='income'?'#3a8670':'inherit'}">${t.transaction_type==='income'?'+':'−'} ${U.money(t.amount,b.budget?.currency_code)}</td><td>${U.edit('transactions',t.id)}</td></tr>`).join('')||'<tr><td colspan="5">No transactions yet. Record your first expense.</td></tr>'}</tbody></table></div>`)}</div><div class="stack">${U.section('Where it went',Object.entries(categories).map(([c,total],i)=>`<div class="attendance-line"><div class="row"><span>${U.esc(c)}</span><strong>${U.money(total,b.budget?.currency_code)}</strong></div><div class="progress"><i style="width:${b.spent?total/b.spent*100:0}%;opacity:${1-i*.15}"></i></div></div>`).join('')||U.empty('Your spending breakdown will appear here.'))}${U.section('Make it work for you',`<div class="note">${U.icon('info')}<span>Your remaining budget is your monthly limit minus expenses. Income is shown separately, so receiving money doesn’t automatically raise your spending limit.</span></div>`)}</div></div>`});
document.addEventListener('change',e=>{if(e.target.id==='budget-month'){month=e.target.value;update()}});document.addEventListener('click',e=>{let b=e.target.closest('[data-type]');if(b){type=b.dataset.type;update()}});
